-- Y3D Creations — troca o catálogo antigo pelos produtos, fotos e preços reais (para bancos JÁ criados).
-- Aplique uma vez no MySQL do projeto. Só usa UPDATE/DELETE com WHERE.
SET NAMES utf8mb4;

INSERT INTO produtos (id, nome, descricao, preco, estoque, categoria_id, emoji, imagens, personalizacoes, detalhes, avaliacao, total_avaliacoes) VALUES (1, 'Chaveiros Nomes BTS', 'Chaveiros com o nome de cada integrante em relevo vermelho sobre base branca, com corrente de bolinhas. Vendidos por unidade.', 8.00, 100, 10, '🔑', '["/img/produtos/chaveiros-nomes-bts.jpg"]', '["Nome ou frase gravada", "Cores personalizadas"]', '["Peça física impressa em 3D pela Y3D Creations"]', NULL, 0)
ON DUPLICATE KEY UPDATE nome=VALUES(nome), descricao=VALUES(descricao), preco=VALUES(preco), estoque=VALUES(estoque), categoria_id=VALUES(categoria_id), emoji=VALUES(emoji), imagens=VALUES(imagens), personalizacoes=VALUES(personalizacoes), detalhes=VALUES(detalhes), avaliacao=VALUES(avaliacao), total_avaliacoes=VALUES(total_avaliacoes);

