-- Produtos antigos (ids 10 a 26): apaga os que nunca foram pedidos e zera o estoque dos que já têm pedido.
DELETE FROM produtos WHERE id BETWEEN 10 AND 26 AND id NOT IN (SELECT produto_id FROM pedido_itens);
UPDATE produtos SET estoque = 0 WHERE id BETWEEN 10 AND 26;
